L000044	\title{Compatible Instability: Gauge Constraints of Elasticity Inherited by Electronic Nematic Criticality}
L000045	\author{W. Joe Meese}
L000046	\affiliation{Department of Physics, The Grainger College of Engineering, University of Illinois Urbana-Champaign, Urbana, IL 61801, USA}
L000047	\affiliation{Anthony J. Leggett Institute for Condensed Matter Theory, The Grainger College of Engineering, University of Illinois Urbana-Champaign, Urbana, IL 61801, USA}
L000048	\author{Rafael M. Fernandes}
L000049	\affiliation{Department of Physics, The Grainger College of Engineering, University of Illinois Urbana-Champaign, Urbana, IL 61801, USA}
